const cfg = $input.first().json;
const kws = String(cfg.mots_cles || '').split(',').map(s => s.trim()).filter(Boolean);
const uniq = Array.from(new Set(kws.map(k => k.toLowerCase())));
return uniq.map(k => {
  const params = ['text=' + encodeURIComponent(k), 'sort=time', 'order=desc'];
  if (cfg.budget_max) params.push('price=' + (cfg.prix_min || 0) + '-' + cfg.budget_max);
  if (cfg.region_code) params.push('locations=' + cfg.region_code);
  return { json: { mot_cle: k, searchUrl: 'https://www.leboncoin.fr/recherche?' + params.join('&') } };
});

const cfg = $('Config').first().json;
const bad = ['hs', 'cassé', 'casse', 'fissuré', 'fissure', 'icloud', 'mdm', 'pour pièces', 'pour pieces', 'bloqué', 'bloque', 'verrouillé', 'verrouille', 'frp'];
const acc = ['coque', 'housse', 'chargeur', 'cable', 'câble', 'vitre', 'protection', 'boite vide', 'boîte vide', 'écran seul', 'ecran seul', 'recherche', 'echange', 'échange', 'achète', 'achete'];
const kws = String(cfg.mots_cles || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean).map(k => k.split(' ').filter(Boolean));
const seen = new Set($input.all().map(i => i.json.lien).filter(Boolean));
const hasWord = (text, w) => new RegExp('(^|[^a-zà-ÿ])' + w + '([^a-zà-ÿ]|$)', 'i').test(text);
const out = [];
for (const i of $('Scraper annonces Leboncoin').all()) {
  const r = i.json;
  const url = r.url || r.link || r.ad_url || '';
  const title = r.title || r.subject || '';
  const description = r.description || r.body || '';
  const price = Number(r.price ?? 0) || 0;
  if (!url || seen.has(url)) continue;
  const t = title.toLowerCase();
  if (kws.length && !kws.some(ws => ws.every(w => t.includes(w)))) continue;
  if (price < (cfg.prix_min || 0)) continue;
  if (cfg.budget_max && price > cfg.budget_max) continue;
  if (price < 150 && acc.some(w => hasWord(t, w))) continue;
  const text = (title + ' ' + description).toLowerCase();
  if (bad.some(w => hasWord(text, w))) continue;
  seen.add(url);
  out.push({ json: {
    title, price, description, url,
    city: (typeof r.city === 'string' ? r.city : (r.location && r.location.city) || (r.city && r.city.city)) || '',
    published_at: r.firstPublicationDate || r.published_at || r.publishedAt || r.first_publication_date || '',
    shipping: r.shipping ?? r.shipping_possible ?? false,
  } });
}
out.sort((a, b) => String(b.json.published_at).localeCompare(String(a.json.published_at)));
return out.slice(0, cfg.max_ia || 20);

