const cfg = $('Config').first().json;
return $input.all().map(i => {
  const d = i.json.output ?? i.json;
  const num = v => (typeof v === 'number' && isFinite(v) ? v : null);
  const prix = num(d.prix_negocie_eur);
  const reventeDh = num(d.prix_revente_maroc_dh);
  const reventeFr = num(d.prix_revente_france_eur);
  if (prix === null || (reventeDh === null && reventeFr === null)) {
    return { json: { ...d, lien: d.lien || $('Boucle annonces').last().json.url, marge_nette_eur: null, garder: false } };
  }
  const transportMA = String(d.appareil || '').toLowerCase().includes('macbook') ? 25 : 10;
  const cout = prix + (num(d.frais_accessoires_eur) ?? 0) + (num(d.reserve_eur) ?? 0) + transportMA;
  const margeMA = reventeDh === null ? -Infinity : reventeDh / cfg.taux_dh - cout;
  const margeFR = reventeFr === null ? -Infinity : reventeFr - cout;
  const meilleure = Math.max(margeMA, margeFR);
  return { json: { ...d, lien: $('Boucle annonces').last().json.url,
    points_a_verifier: Array.isArray(d.points_a_verifier) ? d.points_a_verifier : [],
    cout_total_eur: +cout.toFixed(0),
    marge_maroc_eur: isFinite(margeMA) ? +margeMA.toFixed(0) : null,
    marge_maroc_dh: isFinite(margeMA) ? +(margeMA * cfg.taux_dh).toFixed(0) : null,
    marge_france_eur: isFinite(margeFR) ? +margeFR.toFixed(0) : null,
    marge_nette_eur: +meilleure.toFixed(0),
    garder: d.fonctionnel === true && d.risque !== 'élevé' && meilleure >= cfg.marge_min } };
});

